BEGIN;

DO $$ 
DECLARE
    v_topic_id UUID;
BEGIN
    -- Fetch the topic ID (using both possible slugs as fallbacks)
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'clinical-reasoning-diagnosis' LIMIT 1;
    IF v_topic_id IS NULL THEN
        SELECT id INTO v_topic_id FROM topics WHERE slug = 'clinical-reasoning-differential' LIMIT 1;
    END IF;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic not found for slug clinical-reasoning-diagnosis or clinical-reasoning-differential';
    END IF;

    -- Idempotent Insert for MCQs (Batch 2: 451-550)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation)
    SELECT v_topic_id, t.question, t.options, t.correct_index, t.explanation
    FROM (VALUES
        ('According to "Learning Radiology," which density is the most "radiolucent" (black) on a standard Chest X-ray?', '["The ribs", "Another anatomical structure of similar density (like the heart or diaphragm)", "Air-filled lung", "The skin"]'::jsonb, 2, 'Air is the least dense material and appears black on X-ray.'),
        ('Which physical exam finding is the most reliable for diagnosing "Ascites"?', '["Abdominal distention", "Shifting dullness and fluid wave", "Caput medusae", "Bowel sounds"]'::jsonb, 1, 'Shifting dullness has high sensitivity and specificity for intraperitoneal fluid.'),
        ('In clinical reasoning, "System 1" is most prone to which type of error?', '["Mathematical error", "Cognitive biases and heuristic errors", "Slow processing", "Inability to pattern recognize"]'::jsonb, 1, 'Because it is fast and intuitive, it often skips critical steps.'),
        ('Which "red flag" for a sore throat indicates a potentially life-threatening airway emergency?', '["White patches on tonsils", "Difficulty swallowing saliva (drooling) and a \"muffled\" voice", "Tender lymph nodes", "Fever of 102F"]'::jsonb, 1, 'These are signs of epiglottitis or a peritonsillar abscess that can compromise the airway.'),
        ('A patient with "painless" hematuria (blood in urine) over the age of 50 is a concern for:', '["Urinary Tract Infection", "Bladder or Renal Malignancy", "Kidney stones", "Prostatitis"]'::jsonb, 1, 'Painless hematuria in an older adult is malignancy until proven otherwise.'),
        ('Which finding on a Chest X-ray is most specific for "Alveolar" disease (e.g., Pneumonia or Pulmonary Edema)?', '["Increased density", "Volume loss (displacement of fissures/structures toward the opacity)", "Air bronchograms", "Fever"]'::jsonb, 2, 'Air bronchograms (visible air-filled bronchi surrounded by fluid-filled alveoli) prove the disease is in the alveolar space.'),
        ('A "positive" pneumoperitoneum (free air under the diaphragm) on an upright X-ray indicates:', '["Bowel obstruction", "Pneumoperitoneum (free air in the abdomen)", "Constipation", "Gallstones"]'::jsonb, 1, 'This is a surgical emergency indicating a perforated hollow viscus.'),
        ('In clinical reasoning, "Bayesian" logic uses which piece of information to update the post-test probability?', '["The p-value", "The Likelihood Ratio (LR)", "The sample size", "The cost of the test"]'::jsonb, 1, 'The LR allows the clinician to move from pre-test to post-test probability.'),
        ('Which cognitive bias involves the clinician being influenced by a "small sample size" (e.g., \"I''ve never seen X cause Y, so it must not be true\")?', '["Base-rate neglect", "Law of small numbers", "Availability bias", "Framing"]'::jsonb, 1, 'Relying too much on limited personal experience rather than broad evidence.'),
        ('A patient with "jaundice" and "normal" liver enzymes but "high" indirect bilirubin likely has:', '["Hepatitis", "Hemolysis or Gilbert Syndrome", "Biliary obstruction", "Cirrhosis"]'::jsonb, 1, 'Indirect hyperbilirubinemia without enzyme elevation suggests the liver can''t keep up with production (hemolysis) or a conjugation defect.'),
        ('Which physical exam finding is the hallmark of "peritonitis" (inflammation of the peritoneal lining)?', '["Pain on deep palpation", "Rebound tenderness and involuntary guarding", "Absent bowel sounds", "Bloating"]'::jsonb, 1, 'These indicate that the parietal peritoneum is irritated.'),
        ('In clinical reasoning, "Sutton''s Law" is a reminder to:', '["Look for rare causes", "Prioritize the most likely diagnosis first based on prevalence", "Ignore the history", "Always order a CT scan"]'::jsonb, 1, 'Named after a bank robber who went \"where the money is.\"'),
        ('Which "must-not-miss" condition presents with "sudden, localized" limb pain, pallor, and no pulse?', '["Giving oral pain meds", "Emergent surgical or interventional consult for acute limb ischemia", "Ordering an MRI", "Waiting for the morning"]'::jsonb, 1, 'The \"6 Ps\" (Pain, Pallor, Pulselessness, etc.) indicate a surgical emergency.'),
        ('Which cognitive bias involves the clinician being influenced by a "small sample size" from their own experience?', '["Base-rate neglect", "Law of small numbers", "Availability", "Framing"]'::jsonb, 1, 'Relying too much on a few personal cases rather than large-scale evidence.'),
        ('A patient with "hyponatremia" and "low serum osmolality" (< 280) has:', '["Pseudohyponatremia", "True Hypotonic Hyponatremia", "Hypertonic hyponatremia", "Normal sodium"]'::jsonb, 1, 'True hyponatremia is characterized by a drop in serum osmolality.'),
        ('Which reasoning framework focuses on "Must-Not-Miss" conditions that will kill the patient in the next 24 hours?', '["Chronological reasoning", "The \"On Call\" approach", "Pathophysiological reasoning", "Anatomical reasoning"]'::jsonb, 1, 'The \"On Call\" approach prioritizes urgency over diagnostic elegance.'),
        ('A patient with "chronic" microcytic anemia and a "normal" RDW (Red Cell Distribution Width) is more likely to have:', '["Iron deficiency", "Thalassemia trait", "Acute blood loss", "Lead poisoning"]'::jsonb, 1, 'In Thalassemia, all cells are uniformly small (low RDW); in Iron deficiency, there is more variation as the iron runs out (high RDW).'),
        ('Which cognitive bias involves judging a patient''s "non-compliance" as a personality flaw rather than considering situational factors (e.g., poverty)?', '["Fundamental attribution error", "Confirmation bias", "Outcome bias", "Anchoring"]'::jsonb, 0, 'This is a common bias in how clinicians view \"difficult\" patients.'),
        ('On a lab panel, a patient with "high calcium" and "low phosphorus" likely has:', '["Renal failure", "Primary Hyperparathyroidism", "Vitamin D deficiency", "Bone metastasis"]'::jsonb, 1, 'PTH causes the kidney to dump phosphorus and reabsorb calcium.'),
        ('Which "must-not-miss" cause of acute "back pain" should be ruled out in an elderly patient with a history of HTN?', '["Muscle strain", "Abdominal Aortic Aneurysm (AAA) rupture", "Herniated disc", "Osteoarthritis"]'::jsonb, 1, 'Rupturing AAA can present as severe back or flank pain and is a medical emergency.'),
        ('According to the "SNOOP" mnemonic for headache red flags, what does the "O" stand for?', '["Onset (Sudden/Thunderclap)", "Old age (> 50)", "Oxygen saturation", "Ordering labs"]'::jsonb, 0, 'Sudden onset is a major red flag for intracranial hemorrhage.'),
        ('In clinical reasoning, "System 2" thinking is often described as "metacognitive." What does this mean?', '["It is very fast", "It involves thinking about the thinking process itself", "It uses emotions", "It relies on intuition"]'::jsonb, 1, 'Metacognition allows a clinician to consciously monitor their reasoning for errors and biases.'),
        ('A patient with "chronic" abdominal pain that is "relieved by defecation" likely has:', '["Colon cancer", "Irritable Bowel Syndrome (IBS)", "Celiac disease", "Pancreatitis"]'::jsonb, 1, 'Pain relief after BM is a core component of the Rome criteria for IBS.'),
        ('Which lab test is the most important "initial" step for an elderly patient with new-onset confusion (Delirium)?', '["Brain MRI", "Urinalysis and Fingerstick Glucose", "Lumbar puncture", "Liver biopsy"]'::jsonb, 1, 'UTIs and hypoglycemia/hyperglycemia are extremely common causes of delirium in the elderly.'),
        ('According to "Learning Radiology," a "wedge-shaped" opacity on a peripheral lung field in a patient with pleuritic pain is:', '["Pneumonia", "Hampton''s Hump (Pulmonary Infarction from PE)", "Lung cancer", "Atelectasis"]'::jsonb, 1, 'This is a classic sign of pulmonary infarction following a pulmonary embolism.'),
        ('Which cognitive bias involves a clinician being influenced by a "recent" case of a rare disease and over-diagnosing it in subsequent patients?', '["Confirmation bias", "Availability bias", "Anchoring", "Sunk cost"]'::jsonb, 1, 'Recent memory makes the diagnosis seem more \"available.\"'),
        ('A patient with "chest pain" and "ST-elevation" in leads V1-V4 is having an MI in which location?', '["Anterior/Septal (LAD)", "Inferior (RCA)", "Lateral (LCx)", "Posterior"]'::jsonb, 0, 'V1-V4 view the front and septum of the heart.'),
        ('In clinical reasoning, the "Law of Parsimony" (Occam''s Razor) suggests:', '["One patient can have many diseases", "The simplest explanation is usually the correct one", "Always use the most complex test", "Never trust the lab"]'::jsonb, 1, 'Try to find one diagnosis that explains all the findings.'),
        ('A patient with "lower extremity swelling" that is "unilateral" and "tender" is a "horses" case for:', '["Heart failure", "DVT (Deep Vein Thrombosis)", "Lymphedema", "Cirrhosis"]'::jsonb, 1, 'Unilateral symptoms suggest a local (e.g., clot) rather than systemic (e.g., heart) problem.'),
        ('In a patient with "altered mental status," what is the most important "immediate" lab test after glucose?', '["Head CT", "ABG/VBG to check for CO2 narcosis or hypoxia", "Liver enzymes", "CBC"]'::jsonb, 1, 'Hypercapnia (high CO2) is a very common cause of somnolence and confusion.'),
        ('Which cognitive bias involves the clinician being more likely to diagnose a disease that they have "just read about"?', '["Availability bias", "Representativeness bias", "Anchoring", "Confirmation bias"]'::jsonb, 0, 'Recent information is the most \"available\" in the mind.'),
        ('A patient with "chest pain" that is relieved by "nitroglycerin" but has "normal" troponins likely has:', '["Myocardial Infarction", "Stable or Unstable Angina", "GERD", "Muscular strain"]'::jsonb, 1, 'Nitroglycerin relief suggests ischemia, but the lack of troponin rise means no permanent necrosis (yet).'),
        ('According to the "On Call" approach, a patient with "hypotension" and "fever" should be given:', '["Oral antibiotics", "Immediate IV fluid bolus and broad-spectrum antibiotics", "A cooling blanket", "Repeat BP in 1 hour"]'::jsonb, 1, 'The priority is stabilizing the \"tank\" and treating the source in suspected sepsis.'),
        ('Which cognitive bias involves the clinician \"downplaying\" the severity of a patient''s condition because the clinician is tired (end of shift)?', '["Omission bias", "Commission bias", "Availability bias", "Affective bias"]'::jsonb, 0, 'Fatigue leads to the \"let''s just wait\" mentality.'),
        ('A patient with "acute abdominal pain" and "shoulder pain" likely has:', '["Shoulder injury", "Diaphragmatic irritation (Kehr sign) from blood or air in the peritoneum", "Heart attack", "Anxiety"]'::jsonb, 1, 'Referred pain to the shoulder is a classic sign of diaphragmatic irritation.'),
        ('Which physical exam finding is the most specific for "Chronic Obstructive Pulmonary Disease" (COPD)?', '["Wheezing", "Increased anteroposterior (AP) diameter (Barrel chest)", "Cough", "Fever"]'::jsonb, 1, 'Hyperinflation of the lungs over time leads to the barrel chest deformity.'),
        ('In clinical reasoning, "Sutton''s Law" is based on the logic of:', '["Pre-test probability (Prevalence)", "Sensitivity", "Specificity", "Likelihood ratios"]'::jsonb, 0, 'Go for the most likely diagnosis first.'),
        ('A patient with "low sodium" and "high urine osmolality" (> 100) likely has:', '["SIADH (Syndrome of Inappropriate ADH)", "Diabetes Insipidus", "Dehydration", "Polydipsia"]'::jsonb, 0, 'In SIADH, the body is inappropriately concentrating the urine despite the blood being dilute (low sodium).'),
        ('Which cognitive bias describes the clinician''s tendency to only look for evidence that "confirms" their initial hunch?', '["Availability bias", "Confirmation bias", "Anchoring", "Sunk cost fallacy"]'::jsonb, 1, 'This leads to ignoring \"red flags\" that point to other diagnoses.'),
        ('A patient with "upper GI bleeding" and a "history of cirrhosis" is a concern for:', '["Peptic ulcer", "Esophageal Varices", "Mallory-Weiss tear", "Gastritis"]'::jsonb, 1, 'Portal hypertension in cirrhosis leads to high-pressure varices that can bleed catastrophically.'),
        ('According to "Bates," a "positive" Babinski sign (up-going toe) indicates:', '["Lower Motor Neuron (LMN) lesion", "Upper Motor Neuron (UMN) lesion", "Normal finding in adults", "Peripheral neuropathy"]'::jsonb, 1, 'UMN lesions occur in the brain or spinal cord.'),
        ('Which reasoning tool is most useful for deciding if a patient with "pharyngitis" needs an antibiotic?', '["The Centor Criteria", "The Wells Score", "The SNOOP mnemonic", "The ABCDE approach"]'::jsonb, 0, 'Centor helps estimate the probability of Group A Strep.'),
        ('A patient with "acute onset" of "flank pain" and "hematuria" is a "horses" case for:', '["Renal failure", "Nephrolithiasis (Kidney stone)", "Bladder cancer", "UTI"]'::jsonb, 1, 'Sudden, severe, colicky flank pain is the hallmark of stones.'),
        ('Which cognitive bias involves the clinician being influenced by "how" a choice is presented (e.g., 90% survival vs 10% mortality)?', '["Anchoring bias", "Framing effect", "Outcome bias", "Commission bias"]'::jsonb, 1, 'The frame of reference changes the perceived risk.'),
        ('A patient with "fever," "headache," and "nuchal rigidity" (stiff neck) has:', '["Meningitis", "Tension headache", "Migraine", "Encephalitis"]'::jsonb, 0, 'The classic triad for meningeal inflammation.'),
        ('According to the "On Call" approach, a patient with "tachycardia" and "shortness of breath" should first have their _____ checked:', '["Hemoglobin", "Oxygen Saturation and Heart Rate (ABCs)", "Potassium", "Chest X-ray"]'::jsonb, 1, 'Always start with the ABCs and vital signs.'),
        ('Which cognitive bias involves the clinician \"continuing\" a diagnostic test that is no longer useful because they already started it?', '["Sunk cost fallacy", "Anchoring bias", "Confirmation bias", "Availability bias"]'::jsonb, 0, 'Persisting in a path because of resources already spent.'),
        ('A patient with "jaundice" and "high ALT/AST" (> 1000) likely has:', '["Biliary obstruction", "Acute Viral or Toxic Hepatitis", "Gilbert syndrome", "Cirrhosis"]'::jsonb, 1, 'Very high enzyme levels indicate acute, massive liver cell injury.'),
        ('Which physical exam finding has the highest "sensitivity" for heart failure?', '["S3 gallop", "Jugular Venous Distension (JVD)", "Bilateral crackles", "Bilateral pedal edema"]'::jsonb, 2, 'While crackles and edema are common, they are found in many patients with heart failure (high sensitivity), though the S3 is more specific.'),
        ('In clinical reasoning, "Metacognition" is the primary strategy for:', '["Memorizing more facts", "Reducing cognitive biases by reflecting on one''s own thinking", "Ordering more labs", "Speeding up diagnosis"]'::jsonb, 1, 'Metacognition is the \"System 2\" process of checking \"System 1\" for errors.'),
        ('Which lab test is most useful for "ruling out" Pulmonary Embolism in a patient with a "low" pre-test probability?', '["D-dimer", "CT Angiogram", "ABG", "CXR"]'::jsonb, 0, 'A negative D-dimer has a very high negative predictive value in low-risk patients.'),
        ('A patient with "acute abdominal pain" that radiates to the "back" and is accompanied by "vomiting" likely has:', '["Appendicitis", "Acute Pancreatitis", "Cholecystitis", "IBS"]'::jsonb, 1, 'The retroperitoneal location of the pancreas leads to radiation to the back.'),
        ('Which cognitive bias involves the clinician being influenced by a "small sample size" from their own experience?', '["Base-rate neglect", "Law of small numbers", "Availability", "Framing"]'::jsonb, 1, 'Relying too much on a few personal cases rather than large-scale evidence.'),
        ('According to the "On Call" approach, a patient with a "high potassium" (> 6.5) and "ECG changes" needs:', '["A repeat lab test", "Immediate IV Calcium and measures to lower potassium", "A psychiatric consult", "Observation"]'::jsonb, 1, 'ECG changes in hyperkalemia are a medical emergency.'),
        ('Which cognitive bias involves the clinician \"downplaying\" the severity of a patient''s condition because the clinician is tired (end of shift)?', '["Omission bias", "Commission bias", "Availability bias", "Affective bias"]'::jsonb, 0, 'Fatigue leads to the \"let''s just wait\" mentality.'),
        ('A patient with "chronic" abdominal pain that is "relieved by defecation" likely has:', '["Colon cancer", "Irritable Bowel Syndrome (IBS)", "Celiac disease", "Pancreatitis"]'::jsonb, 1, 'Pain relief after BM is a core component of the Rome criteria for IBS.'),
        ('Which lab test is the most important "initial" step for an elderly patient with new-onset confusion (Delirium)?', '["Brain MRI", "Urinalysis and Fingerstick Glucose", "Lumbar puncture", "Liver biopsy"]'::jsonb, 1, 'UTIs and hypoglycemia/hyperglycemia are extremely common causes of delirium in the elderly.'),
        ('According to "Learning Radiology," a "wedge-shaped" opacity on a peripheral lung field in a patient with pleuritic pain is:', '["Pneumonia", "Hampton''s Hump (Pulmonary Infarction from PE)", "Lung cancer", "Atelectasis"]'::jsonb, 1, 'This is a classic sign of pulmonary infarction following a pulmonary embolism.'),
        ('Which cognitive bias involves a clinician being influenced by a "recent" case of a rare disease and over-diagnosing it in subsequent patients?', '["Confirmation bias", "Availability bias", "Anchoring", "Sunk cost"]'::jsonb, 1, 'Recent memory makes the diagnosis seem more \"available.\"'),
        ('A patient with "chest pain" and "ST-elevation" in leads V1-V4 is having an MI in which location?', '["Anterior/Septal (LAD)", "Inferior (RCA)", "Lateral (LCx)", "Posterior"]'::jsonb, 0, 'V1-V4 view the front and septum of the heart.'),
        ('In clinical reasoning, the "Law of Parsimony" (Occam''s Razor) suggests:', '["One patient can have many diseases", "The simplest explanation is usually the correct one", "Always use the most complex test", "Never trust the lab"]'::jsonb, 1, 'Try to find one diagnosis that explains all the findings.'),
        ('A patient with "lower extremity swelling" that is "unilateral" and "tender" is a "horses" case for:', '["Heart failure", "DVT (Deep Vein Thrombosis)", "Lymphedema", "Cirrhosis"]'::jsonb, 1, 'Unilateral symptoms suggest a local (e.g., clot) rather than systemic (e.g., heart) problem.'),
        ('In a patient with "altered mental status," what is the most important "immediate" lab test after glucose?', '["Head CT", "ABG/VBG to check for CO2 narcosis or hypoxia", "Liver enzymes", "CBC"]'::jsonb, 1, 'Hypercapnia (high CO2) is a very common cause of somnolence and confusion.'),
        ('Which cognitive bias involves the clinician being more likely to diagnose a disease that they have "just read about"?', '["Availability bias", "Representativeness bias", "Anchoring", "Confirmation bias"]'::jsonb, 0, 'Recent information is the most \"available\" in the mind.'),
        ('A patient with "chest pain" that is relieved by "nitroglycerin" but has "normal" troponins likely has:', '["Myocardial Infarction", "Stable or Unstable Angina", "GERD", "Muscular strain"]'::jsonb, 1, 'Nitroglycerin relief suggests ischemia, but the lack of troponin rise means no permanent necrosis (yet).'),
