        ('In a patient with "altered mental status," what is the most important "immediate" lab test after glucose?', '["Head CT", "ABG/VBG to check for CO2 narcosis or hypoxia", "Liver enzymes", "CBC"]'::jsonb, 1, 'Hypercapnia (high CO2) is a very common cause of somnolence and confusion.'),
        ('Which cognitive bias involves the clinician being more likely to diagnose a disease that they have "just read about"?', '["Availability bias", "Representativeness bias", "Anchoring", "Confirmation bias"]'::jsonb, 0, 'Recent information is the most \"available\" in the mind.'),
        ('A patient with "chest pain" that is relieved by "nitroglycerin" but has "normal" troponins likely has:', '["Myocardial Infarction", "Stable or Unstable Angina", "GERD", "Muscular strain"]'::jsonb, 1, 'Nitroglycerin relief suggests ischemia, but the lack of troponin rise means no permanent necrosis (yet).'),
        ('According to the "On Call" approach, a patient with "hypotension" and "fever" should be given:', '["Oral antibiotics", "Immediate IV fluid bolus and broad-spectrum antibiotics", "A cooling blanket", "Repeat BP in 1 hour"]'::jsonb, 1, 'The priority is stabilizing the \"tank\" and treating the source in suspected sepsis.'),
        ('Which cognitive bias involves the clinician \"downplaying\" the severity of a patient''s condition because the clinician is tired (end of shift)?', '["Omission bias", "Commission bias", "Availability bias", "Affective bias"]'::jsonb, 0, 'Fatigue leads to the \"let''s just wait\" mentality.')
    ) AS t(question, options, correct_index, explanation)
    WHERE NOT EXISTS (
        SELECT 1 FROM mcqs m 
        WHERE m.topic_id = v_topic_id 
        AND m.question = t.question
    );

    RAISE NOTICE 'SUCCESS: Batch 2 (MCQs 451-550) processed idempotently with fixed JSON syntax.';
END $$;

COMMIT;
